-- Each case is one transaction and always rolls back.

-- @case 1: two phones give two rows (unknown phone type NULL); no email NULL; '' kept, not NULL; xml passed through (empty element <fax/>); missing address, person or country drops the employee
BEGIN;
DELETE FROM humanresources.employee;
DELETE FROM person.address;
DELETE FROM person.business_entity_address;
DELETE FROM person.country_region;
DELETE FROM person.email_address;
DELETE FROM person.person;
DELETE FROM person.person_phone;
DELETE FROM person.phone_number_type;
DELETE FROM person.state_province;
INSERT INTO humanresources.employee ("BusinessEntityID", "JobTitle") VALUES
  ('1', 'Job 1'),
  ('2', 'Job 2'),
  ('3', 'Job 3'),
  ('4', 'Job 4'),
  ('5', 'Job 5');
INSERT INTO person.address ("AddressID", "AddressLine1", "AddressLine2", "City", "StateProvinceID", "PostalCode") VALUES
  ('1', '1 Main St', NULL, 'Bothell', '1', '98011'),
  ('2', '2 Main St', '', 'Bothell', '1', '98011'),
  ('3', '3 Main St', NULL, 'Bothell', '2', '98011');
INSERT INTO person.business_entity_address ("BusinessEntityID", "AddressID") VALUES
  ('1', '1'),
  ('2', '2'),
  ('4', '1'),
  ('5', '3');
INSERT INTO person.country_region ("CountryRegionCode", "Name") VALUES
  ('US', 'United States');
INSERT INTO person.email_address ("BusinessEntityID", "EmailAddress") VALUES
  ('2', 'b@example.com');
INSERT INTO person.person ("BusinessEntityID", "Title", "FirstName", "MiddleName", "LastName", "Suffix", "EmailPromotion", "AdditionalContactInfo") VALUES
  ('1', NULL, 'First1', NULL, 'Last1', NULL, '0', '<info><phone>555-0100</phone><fax/></info>'),
  ('2', '', 'First2', 'B', 'Last2', 'Jr.', '1', NULL),
  ('3', NULL, 'First3', NULL, 'Last3', NULL, '0', NULL),
  ('5', NULL, 'First5', NULL, 'Last5', NULL, '0', NULL);
INSERT INTO person.person_phone ("BusinessEntityID", "PhoneNumber", "PhoneNumberTypeID") VALUES
  ('1', '555-0100', '1'),
  ('1', '555-0199', '9');
INSERT INTO person.phone_number_type ("PhoneNumberTypeID", "Name") VALUES
  ('1', 'Cell');
INSERT INTO person.state_province ("StateProvinceID", "CountryRegionCode", "Name") VALUES
  ('1', 'US', 'Washington'),
  ('2', 'FR', 'Ile-de-France');
CREATE TEMP TABLE pp_actual ON COMMIT DROP AS
SELECT "BusinessEntityID", "Title", "FirstName", "MiddleName", "LastName", "Suffix", "JobTitle", "PhoneNumber", "PhoneNumberType", "EmailAddress", "EmailPromotion", "AddressLine1", "AddressLine2", "City", "StateProvinceName", "PostalCode", "CountryRegionName", "AdditionalContactInfo"::text AS "AdditionalContactInfo" FROM (SELECT * FROM humanresources.v_employee) AS pp_q;
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['BusinessEntityID', 'Title', 'FirstName', 'MiddleName', 'LastName', 'Suffix', 'JobTitle', 'PhoneNumber', 'PhoneNumberType', 'EmailAddress', 'EmailPromotion', 'AddressLine1', 'AddressLine2', 'City', 'StateProvinceName', 'PostalCode', 'CountryRegionName', 'AdditionalContactInfo']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 two phones give two rows (unknown phone type NULL); no email NULL; kept, not NULL; xml passed through…', got, ARRAY['BusinessEntityID', 'Title', 'FirstName', 'MiddleName', 'LastName', 'Suffix', 'JobTitle', 'PhoneNumber', 'PhoneNumberType', 'EmailAddress', 'EmailPromotion', 'AddressLine1', 'AddressLine2', 'City', 'StateProvinceName', 'PostalCode', 'CountryRegionName', 'AdditionalContactInfo']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected VALUES
  ('1', NULL, 'First1', NULL, 'Last1', NULL, 'Job 1', '555-0100', 'Cell', NULL, '0', '1 Main St', NULL, 'Bothell', 'Washington', '98011', 'United States', '<info><phone>555-0100</phone><fax/></info>'),
  ('1', NULL, 'First1', NULL, 'Last1', NULL, 'Job 1', '555-0199', NULL, NULL, '0', '1 Main St', NULL, 'Bothell', 'Washington', '98011', 'United States', '<info><phone>555-0100</phone><fax/></info>'),
  ('2', '', 'First2', 'B', 'Last2', 'Jr.', 'Job 2', NULL, NULL, 'b@example.com', '1', '2 Main St', '', 'Bothell', 'Washington', '98011', 'United States', NULL);
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 two phones give two rows (unknown phone type NULL); no email NULL; kept, not NULL; xml passed through…', missing, extra;
  END IF;
END $pp$;
ROLLBACK;

